   <section className="welcome-card"><div><small>02 · WHAT BROUGHT YOU HERE?</small><h2>Choose your Palace doors.</h2><p>This simply helps arrange your home. Pick as many as you like.</p></div><div className="welcome-choice-grid">{intentionOptions.map(([value,label])=><button type="button" key={value} className={intentions.includes(value)?'selected':''} onClick={()=>toggle(intentions,setIntentions,value)} aria-pressed={intentions.includes(value)}>{label}</button>)}</div></section>
