 const storyCta=w=>reopened(w)?'Read new chapter →':stateFor(w).progress&&!stateFor(w).progress.completed?'Continue reading →':finished(w)?'Read again →':'Enter story →';
 const filtered=roomWorks.filter(w=>(rating==='all'||w.rating===rating)&&(status==='all'||w.completion_status===status)&&(!query.trim()||[w.title,w.summary,w.profiles?.display_name,w.profiles?.username,...workTags(w).flatMap(t=>[t.name,t.category])].filter(Boolean).join(' ').toLowerCase().includes(query.toLowerCase())));
 const updated=[...roomWorks].sort((a,b)=>new Date(b.last_published_at||0)-new Date(a.last_published_at||0));
 const debuts=[...roomWorks].sort((a,b)=>new Date(b.first_published_at||b.last_published_at||0)-new Date(a.first_published_at||a.last_published_at||0));
 const following=[...roomWorks].filter(w=>stateFor(w).following).sort((a,b)=>new Date(b.last_published_at||0)-new Date(a.last_published_at||0));
 const continueReading=[...roomWorks].filter(needsReading).sort((a,b)=>new Date(stateFor(b).progress?.updated_at||0)-new Date(stateFor(a).progress?.updated_at||0));
