 function openWorkReport(){setReportReason('');setReportOpen(true)}
 async function submitWorkReport(){if(!session||!data||!reportReason.trim())return;try{await submitCommunityReport(session.user.id,'work',data.id,reportReason,{slug:data.slug,title:data.title,author_id:data.author_id});setReportOpen(false);setNotice('Report sent to Palace Council for review.')}catch(e){setError(e.message)}}
