 async function shareWork(){if(!data)return;try{const url=window.location.href;if(navigator.share)await navigator.share({title:data.title,text:data.summary||'A story from The Starry Palace',url});else await navigator.clipboard.writeText(url);if(session&&session.user.id!==data.author_id){const result=await recordPalaceShare(data.id);const earned=Number(result?.giver_points_awarded_now||0);setNotice((navigator.share?'Shared':'Link copied')+(earned?' · +'+earned+' Celestial Points.':'.'))}else setNotice(navigator.share?'Shared.':'Link copied.')}catch(e){if(e?.name!=='AbortError')setError(e.message)}}
 async function keep(kind){if(!session){setNotice('Sign in to keep this story in your Palace.');return}try{setReaderBusy(kind);if(kind==='save'){const next=!readerState.saved;await setWorkSaved(session.user.id,data.id,next);setReaderState(v=>({...v,saved:next}));setNotice(next?'Saved to My Library.':'Removed from My Library.')}else{const next=!readerState.following;await setWorkFollowing(session.user.id,data.id,next);setReaderState(v=>({...v,following:next}));setNotice(next?'You are following this story.':'Story updates unfollowed.')}}catch(e){setError(e.message)}finally{setReaderBusy('')}}
 if(data===null)return <Frame><div className="live-state">This story is not available.</div></Frame>;
 const readable=data?.chapters.filter(ch=>ch.status==='published'||session?.user?.id===data.author_id)||[];
 const publicChapters=data?.chapters.filter(ch=>ch.status==='published')||[];
 const totalWords=readable.reduce((n,ch)=>n+Number(ch.word_count||0),0);
 const first=readable[0];
 const resumeChapter=readerState.progress?.chapter_id&&readable.find(ch=>ch.id===readerState.progress.chapter_id);
 const updatedSinceRead=!!(readerState.progress?.updated_at&&data?.last_published_at&&new Date(data.last_published_at)>new Date(readerState.progress.updated_at));
 const reopenedAfterFinish=!!readerState.progress?.completed&&updatedSinceRead;
